INSERT INTO "shows" ("id", "source", "date", "time", "venue", "comedian_names", "raw_json", "created_at", "availability") VALUES (1, 'comedy-cellar', '2026-04-20', '5:15 pm', 'Smart Girl Dumb Questions Podcast Live', 'Nayeema Raza, Neil deGrasse', '{"source":"comedy-cellar","date":"2026-04-20","time":"5:15 pm","venue":"Smart Girl Dumb Questions Podcast Live","comedians":[{"name":"Nayeema Raza","credits":"Nayeema Raza is a journalist and filmmaker whose work has appeared in The New York Times, New York Magazine, and the Tribeca Film Festival. She frequently guest moderates “Open to Debate.” Nayeema also hosts “Smart Girl Dumb Questions,” which seeks to invite curiosity back into our broader dialogue, and is an adjunct professor at Columbia University, where she teaches a course on technology, media, and the end of trust."},{"name":"Neil deGrasse","credits":"Tyson world-renowned science communicator and astrophysicist. He is the Director of the Hayden Planetarium at the American Museum of Natural History and the author of several bestsllers and awe-inspiring books including his latest, “Take Me To Your Your Leader: Perspectives on Your First Alien Encounter.”"}]}', '2026-04-19 18:19:13', NULL);
