INSERT INTO "shows" ("id", "source", "date", "time", "venue", "comedian_names", "raw_json", "created_at", "availability") VALUES (83, 'comedy-cellar', '2026-05-13', '6:00 pm', 'Live with Nate Silver, Clare Malone and Galen Druke', 'Clare Malone staff writer at The New Yorker covering the media business, journalism, and politics. She previously wrote for FiveThirtyEight, where she reported on class, race, and electoral politics, and covered the 2016 and 2020 Presidential campaigns. Her writing has also appeared in New York, The Atlantic,, Galen Druke founder and host of the, Nate Silver American statistician, political analyst, author, sports gambler, and poker player who analyzes baseball, basketball and elections. He is the founder of FiveThirtyEight and held the position of editor-in-chief there, along with being a special correspondent for', '{"source":"comedy-cellar","date":"2026-05-13","time":"6:00 pm","venue":"Live with Nate Silver, Clare Malone and Galen Druke","comedians":[{"name":"Clare Malone staff writer at The New Yorker covering the media business, journalism, and politics. She previously wrote for FiveThirtyEight, where she reported on class, race, and electoral politics, and covered the 2016 and 2020 Presidential campaigns. Her writing has also appeared in New York, The Atlantic,","credits":"GQ, The Columbia Journalism Review, and Harper’s."},{"name":"Galen Druke founder and host of the","credits":"GD POLITICS podcast. He previously hosted and produced the FiveThirtyEight Politics podcast, where he covered American elections for nearly a decade. His reporting and analysis have also regularly appeared on ABC News and the BBC. He began his career working for NPR affiliates in Wisconsin, New York City and Baltimore, where he attended The Johns Hopkins University. He is an executive member of the International Academy of Digital Arts and Sciences and lives in New York City."},{"name":"Nate Silver American statistician, political analyst, author, sports gambler, and poker player who analyzes baseball, basketball and elections. He is the founder of FiveThirtyEight and held the position of editor-in-chief there, along with being a special correspondent for","credits":"ABC News until May 2023. Since departing FiveThirtyEight, Silver has been publishing in his online newsletter Silver Bulletin and serves as an advisor to Polymarket"}]}', '2026-04-19 18:27:19', NULL);
